-- Personale sul database (nov 2026): prima i dipendenti erano solo dati fissi dell'app. Ora stanno in beachin.dipendenti
-- e la pagina Personale può importare le buste paga in PDF (i dati principali finiscono nel dipendente, colonna `dati`).
-- Dati sensibili (codice fiscale, IBAN, retribuzioni): niente accesso anon, solo lo staff col permesso Personale.
create table if not exists beachin.dipendenti (
  id text primary key,
  nome text not null,
  cognome text not null,
  codice_fiscale text unique,
  ruolo text not null,
  -- resto del dipendente (contratto, ore, costi, turni, anagrafica, buste paga importate)
  dati jsonb not null default '{}'::jsonb
);

grant select, insert, update, delete on beachin.dipendenti to authenticated, service_role;
revoke all on beachin.dipendenti from anon;
alter table beachin.dipendenti enable row level security;
drop policy if exists "personale lettura" on beachin.dipendenti;
create policy "personale lettura" on beachin.dipendenti for select to authenticated using (beachin.ha_permesso('personale', 1));
drop policy if exists "personale modifica" on beachin.dipendenti;
create policy "personale modifica" on beachin.dipendenti for all to authenticated
  using (beachin.ha_permesso('personale', 2)) with check (beachin.ha_permesso('personale', 2));
do $$
begin
  if not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'beachin' and tablename = 'dipendenti') then
    alter publication supabase_realtime add table beachin.dipendenti;
  end if;
end $$;

